package cube.lab.nativeapp

import android.content.Context
import java.nio.ByteBuffer
import java.nio.ByteOrder

// Kociemba two-phase 3x3 solver + 2x2 corner solver.
// The tables are generated by tools/build-tables.mjs and shipped in assets.

object Kociemba {
    const val N_TWIST = 2187
    const val N_FLIP = 2048
    const val N_SLICE = 495
    const val N_PERM8 = 40320
    const val N_SLICE_PERM = 24

    val MOVE_NAMES: List<String> = buildList {
        for (f in FACE_KEYS) for (s in arrayOf("", "2", "'")) add(f + s)
    }
    private val MOVE_FACE = IntArray(18) { faceIndexOf(MOVE_NAMES[it][0]) }
    private val MOVE_OPPOSITE = intArrayOf(1, 0, 3, 2, 5, 4)
    private val PHASE2_MOVES = intArrayOf(0, 1, 2, 3, 4, 5, 13, 16, 7, 10)
    private val PHASE2_FACES = IntArray(10) { MOVE_FACE[PHASE2_MOVES[it]] }

    private var tables: Tables? = null

    class Tables(
        val twistMove: ShortArray,
        val flipMove: ShortArray,
        val sliceMove: ShortArray,
        val cpMove: ShortArray,
        val ep8Move: ShortArray,
        val spMove: ShortArray,
        val pruneTwistSlice: ByteArray,
        val pruneFlipSlice: ByteArray,
        val pruneCpSp: ByteArray,
        val pruneEp8Sp: ByteArray,
        val pruneTwist: ByteArray,
        val pruneCp: ByteArray,
    )

    fun ensure(context: Context): Boolean {
        if (tables != null) return true
        return try {
            loadFromBytes(context.assets.open("cube3.bin").readBytes())
        } catch (t: Throwable) {
            false
        }
    }

    fun loadFromBytes(bytes: ByteArray): Boolean = synchronized(this) {
        if (tables != null) return true
        tables = try {
            parse(bytes)
        } catch (t: Throwable) {
            null
        }
        tables != null
    }

    fun ready(): Boolean = tables != null

    private fun parse(bytes: ByteArray): Tables {
        val bb = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
        val layout = arrayOf(
            Triple("twistMove", 2, 2187 * 18),
            Triple("flipMove", 2, 2048 * 18),
            Triple("sliceMove", 2, 495 * 18),
            Triple("cpMove", 2, 40320 * 10),
            Triple("ep8Move", 2, 40320 * 10),
            Triple("spMove", 2, 24 * 10),
            Triple("pruneTwistSlice", 1, 2187 * 495),
            Triple("pruneFlipSlice", 1, 2048 * 495),
            Triple("pruneCpSp", 1, 40320 * 24),
            Triple("pruneEp8Sp", 1, 40320 * 24),
            Triple("pruneTwist", 1, 2187),
            Triple("pruneCp", 1, 40320),
        )
        val offsets = HashMap<String, Int>()
        var offset = 0
        for ((name, size, len) in layout) {
            if (offset % size != 0) offset++
            offsets[name] = offset
            offset += len * size
        }
        fun shortArr(name: String, len: Int): ShortArray {
            val off = offsets[name]!!
            return ShortArray(len) { (bb.getShort(off + it * 2).toInt() and 0xFFFF).toShort() }
        }
        fun byteArr(name: String, len: Int): ByteArray {
            val off = offsets[name]!!
            return bytes.copyOfRange(off, off + len)
        }
        return Tables(
            shortArr("twistMove", 2187 * 18),
            shortArr("flipMove", 2048 * 18),
            shortArr("sliceMove", 495 * 18),
            shortArr("cpMove", 40320 * 10),
            shortArr("ep8Move", 40320 * 10),
            shortArr("spMove", 24 * 10),
            byteArr("pruneTwistSlice", 2187 * 495),
            byteArr("pruneFlipSlice", 2048 * 495),
            byteArr("pruneCpSp", 40320 * 24),
            byteArr("pruneEp8Sp", 40320 * 24),
            byteArr("pruneTwist", 2187),
            byteArr("pruneCp", 40320),
        )
    }

    private fun s(arr: ShortArray, i: Int): Int = arr[i].toInt() and 0xFFFF
    private fun b(arr: ByteArray, i: Int): Int = arr[i].toInt() and 0xFF

    // ------------------------------------------------------------ coordinates

    fun twistOf(co: IntArray): Int {
        var t = 0
        for (i in 0 until 7) t = t * 3 + co[i]
        return t
    }

    fun twistTo(t0: Int): IntArray {
        var t = t0
        val co = IntArray(8)
        for (i in 6 downTo 0) {
            co[i] = t % 3
            t /= 3
        }
        var sum = 0
        for (i in 0 until 7) sum += co[i]
        co[7] = (3 - sum % 3) % 3
        return co
    }

    fun flipOf(eo: IntArray): Int {
        var f = 0
        for (i in 0 until 11) f = f * 2 + eo[i]
        return f
    }

    fun flipTo(f0: Int): IntArray {
        var f = f0
        val eo = IntArray(12)
        var sum = 0
        for (i in 10 downTo 0) {
            eo[i] = f and 1
            sum += eo[i]
            f = f shr 1
        }
        eo[11] = sum and 1
        return eo
    }

    private val SLICE_MASKS: List<Int> = run {
        val masks = ArrayList<Int>()
        for (a in 0 until 12) for (b in a + 1 until 12) for (c in b + 1 until 12) for (d in c + 1 until 12) {
            masks.add((1 shl a) or (1 shl b) or (1 shl c) or (1 shl d))
        }
        masks.reverse()
        masks
    }
    private val SLICE_RANK = IntArray(1 shl 12) { -1 }.also { r ->
        SLICE_MASKS.forEachIndexed { i, m -> r[m] = i }
    }

    fun sliceOf(ep: IntArray): Int {
        var mask = 0
        for (i in 0 until 12) if (ep[i] >= 8) mask = mask or (1 shl i)
        return SLICE_RANK[mask]
    }

    fun sliceTo(rank: Int): IntArray {
        val mask = SLICE_MASKS[rank]
        val ep = IntArray(12) { -1 }
        var piece = 8
        for (i in 0 until 12) if ((mask shr i) and 1 != 0) ep[i] = piece++
        var low = 0
        for (i in 0 until 12) if (ep[i] < 0) ep[i] = low++
        return ep
    }

    fun permRank(p: IntArray): Int {
        val n = p.size
        var rank = 0
        for (i in 0 until n) {
            var k = 0
            for (j in i + 1 until n) if (p[j] < p[i]) k++
            rank = rank * (n - i) + k
        }
        return rank
    }

    fun permUnrank(rank0: Int, n: Int): IntArray {
        var rank = rank0
        val digits = IntArray(n)
        for (i in n - 1 downTo 0) {
            digits[i] = rank % (n - i)
            rank /= n - i
        }
        val pool = IntArray(n) { it }
        var count = n
        val out = IntArray(n)
        for (i in 0 until n) {
            val idx = digits[i]
            out[i] = pool[idx]
            for (j in idx until count - 1) pool[j] = pool[j + 1]
            count--
        }
        return out
    }

    // ------------------------------------------------------------ searching

    private var nodes = 0L
    private val nodeLimit = 40_000_000L

    private fun allowed(lastFace: Int, face: Int): Boolean {
        if (lastFace < 0) return true
        if (face == lastFace) return false
        if (face == MOVE_OPPOSITE[lastFace] && face < lastFace) return false
        return true
    }

    private fun searchPhase1(tw0: Int, fl0: Int, sl0: Int, maxDepth: Int): IntArray? {
        val t = tables ?: return null
        val path = IntArray(maxDepth + 1)
        var len = 0
        lateinit var dfs: (Int, Int, Int, Int, Int) -> Boolean
        dfs = fun(tw: Int, fl: Int, sl: Int, depth: Int, lastFace: Int): Boolean {
            if (++nodes > nodeLimit) return false
            val h = maxOf(b(t.pruneTwistSlice, tw * N_SLICE + sl), b(t.pruneFlipSlice, fl * N_SLICE + sl))
            if (h > depth) return false
            if (depth == 0) return tw == 0 && fl == 0 && sl == 0
            for (m in 0 until 18) {
                val face = MOVE_FACE[m]
                if (!allowed(lastFace, face)) continue
                val ntw = s(t.twistMove, tw * 18 + m)
                val nfl = s(t.flipMove, fl * 18 + m)
                val nsl = s(t.sliceMove, sl * 18 + m)
                path[len++] = m
                if (dfs(ntw, nfl, nsl, depth - 1, face)) return true
                len--
            }
            return false
        }
        for (depth in 0..maxDepth) {
            len = 0
            nodes = 0
            if (dfs(tw0, fl0, sl0, depth, -1)) return path.copyOf(len)
            if (nodes > nodeLimit) return null
        }
        return null
    }

    private fun searchPhase2(cp0: Int, ep0: Int, sp0: Int, maxDepth: Int): IntArray? {
        val t = tables ?: return null
        val path = IntArray(maxDepth + 1)
        var len = 0
        lateinit var dfs: (Int, Int, Int, Int, Int) -> Boolean
        dfs = fun(cp: Int, ep: Int, sp: Int, depth: Int, lastFace: Int): Boolean {
            if (++nodes > nodeLimit) return false
            val h = maxOf(b(t.pruneCpSp, cp * N_SLICE_PERM + sp), b(t.pruneEp8Sp, ep * N_SLICE_PERM + sp))
            if (h > depth) return false
            if (depth == 0) return cp == 0 && ep == 0 && sp == 0
            for (k in 0 until 10) {
                val face = PHASE2_FACES[k]
                if (!allowed(lastFace, face)) continue
                val ncp = s(t.cpMove, cp * 10 + k)
                val nep = s(t.ep8Move, ep * 10 + k)
                val nsp = s(t.spMove, sp * 10 + k)
                path[len++] = k
                if (dfs(ncp, nep, nsp, depth - 1, face)) return true
                len--
            }
            return false
        }
        for (depth in 0..maxDepth) {
            len = 0
            nodes = 0
            if (dfs(cp0, ep0, sp0, depth, -1)) return path.copyOf(len)
            if (nodes > nodeLimit) return null
        }
        return null
    }

    private fun applyMoves(state: CubieState, names: List<String>): CubieState {
        val cube = Cube(3)
        var s = state
        for (name in names) {
            val m = cubeMoveState(cube, cube.move(name))
            s = composeStates(s, m)
        }
        return s
    }

    private val moveStateCache = HashMap<Int, List<CubieState>>()

    private fun cubeMoveState(cube: Cube, info: MoveInfo): CubieState {
        val list = moveStateCache.getOrPut(cube.n) {
            val solved = cube.solved()
            Kociemba.MOVE_NAMES.map { name ->
                decodeCubies(cube.apply(solved, cube.move(name)), cube, HOME_COLORS)
                    ?: error("cannot decode move table")
            }
        }
        return list[MOVE_NAMES.indexOf(info.name)]
    }

    private fun isSolvedState(s: CubieState): Boolean {
        for (i in 0 until 8) if (s.cp[i] != i || s.co[i] != 0) return false
        for (i in 0 until 12) if (s.ep[i] != i || s.eo[i] != 0) return false
        return true
    }

    fun isValid3(s: CubieState): Boolean {
        if (s.cp.toSet().size != 8 || s.ep.toSet().size != 12) return false
        var coSum = 0
        var eoSum = 0
        for (i in 0 until 8) {
            if (s.co[i] !in 0..2) return false
            coSum += s.co[i]
        }
        for (i in 0 until 12) {
            if (s.eo[i] !in 0..1) return false
            eoSum += s.eo[i]
        }
        if (coSum % 3 != 0 || eoSum % 2 != 0) return false
        return (permParity(s.cp) xor permParity(s.ep)) == 0
    }

    /** Returns move names, or null if the state cannot be solved. */
    fun solveCube(state: CubieState): List<String>? {
        if (!ready()) return null
        if (!isValid3(state)) return null
        if (isSolvedState(state)) return emptyList()
        val tw0 = twistOf(state.co)
        val fl0 = flipOf(state.eo)
        val sl0 = sliceOf(state.ep)
        val p1 = searchPhase1(tw0, fl0, sl0, 14) ?: return null
        val names1 = p1.map { MOVE_NAMES[it] }
        val mid = applyMoves(state, names1)
        val cp1 = permRank(mid.cp)
        val ep1 = permRank(mid.ep.copyOfRange(0, 8))
        val sp1 = permRank(IntArray(4) { mid.ep[8 + it] - 8 })
        val p2 = searchPhase2(cp1, ep1, sp1, 18) ?: return null
        val names2 = p2.map { MOVE_NAMES[PHASE2_MOVES[it]] }
        val all = names1 + names2
        if (!isSolvedState(applyMoves(state, all))) return null
        return all
    }

    /** 2x2: solve corners only, greedy on the shipped tables. */
    fun solveCorners(cp0: IntArray, co0: IntArray): List<String>? {
        if (!ready()) return null
        if (co0.sum() % 3 != 0) return null
        if (cp0.toSet().size != 8) return null
        val cube = Cube(3)
        val moves = MOVE_NAMES.map { cubeMoveState(cube, cube.move(it)) }
        var cp = cp0.copyOf()
        var co = co0.copyOf()
        var tw = twistOf(co)
        val names = ArrayList<String>()
        while (b(tables!!.pruneTwist, tw) > 0) {
            var stepped = false
            for (m in 0 until 18) {
                val next = composeStates(CubieState(cp, co, IntArray(12) { it }, IntArray(12)), moves[m])
                if (b(tables!!.pruneTwist, twistOf(next.co)) == b(tables!!.pruneTwist, tw) - 1) {
                    names.add(MOVE_NAMES[m])
                    cp = next.cp
                    co = next.co
                    tw = twistOf(co)
                    stepped = true
                    break
                }
            }
            if (!stepped) return null
            if (names.size > 60) return null
        }
        var rank = permRank(cp)
        while (b(tables!!.pruneCp, rank) > 0) {
            var stepped = false
            for (k in 0 until 10) {
                val next = composeStates(
                    CubieState(cp, co, IntArray(12) { it }, IntArray(12)),
                    moves[PHASE2_MOVES[k]],
                )
                if (b(tables!!.pruneCp, permRank(next.cp)) == b(tables!!.pruneCp, rank) - 1) {
                    names.add(MOVE_NAMES[PHASE2_MOVES[k]])
                    cp = next.cp
                    co = next.co
                    rank = permRank(cp)
                    stepped = true
                    break
                }
            }
            if (!stepped) return null
            if (names.size > 60) return null
        }
        return names
    }
}
